import{_t as e,at as t,et as n,it as r,n as i,ot as a,rt as o,xt as s}from"./chunks/framework.C5Z6qjff.js";var c=JSON.parse(`{"title":"Anmelden","description":"","frontmatter":{"title":"Anmelden","covers":{"screens":[],"stories":["US-001"]}},"headers":[],"relativePath":"de/usage/login.md","filePath":"de/usage/login.md"}`),l={name:`de/usage/login.md`};function u(i,c,l,u,d,f){let p=s(`Screenshot`);return e(),o(`div`,null,[c[0]||=r(`<h1 id="anmelden" tabindex="-1">Anmelden <a class="header-anchor" href="#anmelden" aria-label="Permalink to “Anmelden”">​</a></h1><p>Öffne die Weboberfläche und wähle <em>Log in</em>. Die Seite <em>Log in to OEA</em> bietet pro Identity-Provider deiner Organisation einen Button <em>Log in with …</em> und darunter die Anmeldung mit dem lokalen Systemadmin-Konto.</p><p>Die Weboberfläche ist in dieser Version nur auf Englisch verfügbar; dieses Handbuch nennt ihre Beschriftungen deshalb im englischen Original.</p><h2 id="uber-deinen-identity-provider-anmelden" tabindex="-1">Über deinen Identity-Provider anmelden <a class="header-anchor" href="#uber-deinen-identity-provider-anmelden" aria-label="Permalink to “Über deinen Identity-Provider anmelden”">​</a></h2><ol><li>Wähle <em>Log in with</em> und den Namen deines Providers.</li><li>Melde dich wie gewohnt bei deinem Provider an; er schickt dich zurück zu OEA.</li><li>Du bist angemeldet. Die Kopfzeile zeigt <em>Catalogs</em>, dein Profil und <em>Log out</em>.</li></ol><p>Deine Administration muss deine Person angelegt und an deine Identität beim Provider gebunden haben. Ist das nicht der Fall, zeigt die Anmeldeseite <em>Login failed</em> – aus Sicherheitsgründen ohne den genauen Grund; deine Administration findet ihn im Audit-Log. Ist der Provider nicht erreichbar, bittet dich die Seite, es später erneut zu versuchen.</p><p>Deine Rollen kommen aus deinen Gruppen beim Provider. Rollen mit administrativen Berechtigungen gelten nur, wenn du dich beim Provider mit einem zweiten Faktor angemeldet hast.</p><h2 id="mit-dem-lokalen-systemadmin-konto-anmelden" tabindex="-1">Mit dem lokalen Systemadmin-Konto anmelden <a class="header-anchor" href="#mit-dem-lokalen-systemadmin-konto-anmelden" aria-label="Permalink to “Mit dem lokalen Systemadmin-Konto anmelden”">​</a></h2><p>Gib Anmeldename und Passwort des Systemadmin-Kontos ein und wähle <em>Log in</em>. Nach der Setup-Phase fragt die Seite nach dem Code deiner Authenticator-App: Gib ihn ein und wähle <em>Confirm</em>. <em>Start again</em> führt zurück zum Passwortschritt.</p>`,9),a(p,{name:`login`,alt:`Anmeldeseite mit den Providern und der Anmeldung des lokalen Systemadmin-Kontos`}),c[1]||=r(`<ul><li>Nach fünf falschen Codes musst du wieder mit dem Passwort beginnen.</li><li>Nach wiederholt falschen Passwörtern werden weitere Versuche verzögert (höchstens 15 Minuten).</li></ul><h2 id="dein-profil" tabindex="-1">Dein Profil <a class="header-anchor" href="#dein-profil" aria-label="Permalink to “Dein Profil”">​</a></h2><p><em>Profile</em> (<code>/me</code>) zeigt deinen Namen, die Kontoart, ob deine Sitzung mit einem zweiten Faktor bestätigt ist, und deine Rollen. Ist dir noch keine Rolle zugewiesen, sagt dir das Profil das; bitte deine Administration um Zugriff.</p><h2 id="zweiten-faktor-einrichten" tabindex="-1">Zweiten Faktor einrichten <a class="header-anchor" href="#zweiten-faktor-einrichten" aria-label="Permalink to “Zweiten Faktor einrichten”">​</a></h2><p>Das lokale Systemadmin-Konto braucht einen zweiten Faktor, um die Setup-Phase zu beenden (siehe <a href="./../setup/first-administrator">Erster Administrator</a>):</p><ol><li>Wähle in <em>Profile</em> den Button <em>Set up a second factor</em>, dann <em>Set up authenticator app</em>.</li><li>Scanne den QR-Code mit einer Authenticator-App (jede App für zeitbasierte Einmalpasswörter, TOTP).</li><li>Gib den Code aus der App unter <em>Code from the app</em> ein und wähle <em>Confirm</em>.</li></ol>`,6),a(p,{name:`second-factor-enroll`,alt:`Einrichten der Authenticator-App mit QR-Code und Codefeld`}),c[2]||=n(`p`,null,`Die Seite bestätigt, dass die Authenticator-App eingerichtet und die Sitzung bestätigt ist. Das Einrichten eines zweiten Faktors braucht eine Anmeldung innerhalb der letzten 5 Minuten; sonst bittet dich die Seite, dich erneut anzumelden.`,-1),c[3]||=n(`h2`,{id:`sitzungen-und-abmelden`,tabindex:`-1`},[t(`Sitzungen und Abmelden `),n(`a`,{class:`header-anchor`,href:`#sitzungen-und-abmelden`,"aria-label":`Permalink to “Sitzungen und Abmelden”`},`​`)],-1),c[4]||=n(`p`,null,[t(`Wähle `),n(`em`,null,`Log out`),t(` in der Kopfzeile oder in deinem Profil. Eine Sitzung endet außerdem nach 30 Minuten ohne Aktivität und spätestens 12 Stunden nach der Anmeldung.`)],-1)])}var d=i(l,[[`render`,u]]);export{c as __pageData,d as default};